// icons 在初始化时解析好，避免每帧重复解析 SVG。
var icons = func() map[string]*ui.SVG {
	m := make(map[string]*ui.SVG, len(iconSVG))
	for name, s := range iconSVG {
		m[name] = ui.MustParseSVG([]byte(s))
	}
	return m
}()

func icon(name string) *ui.SVG { return icons[name] }
